pragma solidity >=0.8.0;

contract TimestampWidthProbe {
    uint8 public tag;
    uint64 public lastSeen;
    uint256 public count;

    event Tagged(uint8 tag, uint64 seen, address by);

    function snapshot(uint8 t) public {
        tag = t;
        lastSeen = uint64(block.timestamp);
        count += 1;
        emit Tagged(t, lastSeen, msg.sender);
    }

    function mask(uint64 t) public pure returns (uint64) {
        return t & 4294967295;
    }

    function getNow() public view returns (uint256) {
        return block.timestamp;
    }
}
